// Des: Tests for qu-fron-main: dedupe, backoff, DLQ, crash resume
// Flo: temp db > add > due > fail until dead > resume > replay
// I/O: rows > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const fron = @import("qu-fron-main.zig"); const inde = @import("st-page-inde.zig");
const allo = std.testing.allocator;
const Rigg = struct { tmpz: std.testing.TmpDir, dirz: []u8, dbzz: @import("st-stor-sqli.zig").Dbzz, aren: std.heap.ArenaAllocator, pub fn upzz(self: *Rigg) !void { self.tmpz = std.testing.tmpDir(.{}); self.dirz = try std.fmt.allocPrint(allo, ".zig-cache/tmp/{s}", .{self.tmpz.sub_path}); self.dbzz = try inde.pageOpen(allo, std.testing.io, self.dirz); self.aren = std.heap.ArenaAllocator.init(allo); } pub fn down(self: *Rigg) void { self.aren.deinit(); self.dbzz.close(); allo.free(self.dirz); self.tmpz.cleanup(); } };
test "same URL is added once, due rows come oldest first" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try std.testing.expect(try fron.fronAddz(&rig3.dbzz, "http://a/1", "a", 100)); try std.testing.expect(!try fron.fronAddz(&rig3.dbzz, "http://a/1", "a", 200)); try std.testing.expect(try fron.fronAddz(&rig3.dbzz, "http://b/2", "b", 150)); const duez = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 1000, 10); try std.testing.expectEqual(@as(usize, 2), duez.len); try std.testing.expectEqualStrings("http://a/1", duez[0].urlz); const earl = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 120, 10); try std.testing.expectEqual(@as(usize, 1), earl.len); }
test "failures back off, then the poison URL lands in the DLQ" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try fron.fronAddz(&rig3.dbzz, "http://p/x", "p", 0); try fron.fronLock(&rig3.dbzz, "http://p/x"); try std.testing.expect(!try fron.fronFail(&rig3.dbzz, "http://p/x", "Timeout", 1000, 3, 500)); const wait = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 1100, 10); try std.testing.expectEqual(@as(usize, 0), wait.len); const back = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 2100, 10); try std.testing.expectEqual(@as(usize, 1), back.len); try std.testing.expectEqual(@as(i64, 1), back[0].tryz); try std.testing.expect(!try fron.fronFail(&rig3.dbzz, "http://p/x", "Timeout", 3000, 3, 500)); try std.testing.expect(try fron.fronFail(&rig3.dbzz, "http://p/x", "Timeout", 9000, 3, 500)); try std.testing.expectEqual(@as(i64, 1), try fron.fronCont(&rig3.dbzz, 2)); const dead = try fron.fronDead(&rig3.dbzz, rig3.aren.allocator()); try std.testing.expectEqualStrings("Timeout", dead[0].errz); const none = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 99999999, 10); try std.testing.expectEqual(@as(usize, 0), none.len); try fron.fronRetr(&rig3.dbzz, "http://p/x", 10); const again = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 11, 10); try std.testing.expectEqual(@as(usize, 1), again.len); try std.testing.expectEqual(@as(i64, 0), again[0].tryz); }
test "crash resume: claimed rows return to pending, done rows stay done" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); _ = try fron.fronAddz(&rig3.dbzz, "http://a/1", "a", 0); _ = try fron.fronAddz(&rig3.dbzz, "http://a/2", "a", 0); try fron.fronLock(&rig3.dbzz, "http://a/1"); try fron.fronDone(&rig3.dbzz, "http://a/2"); try std.testing.expectEqual(@as(i64, 1), try fron.fronResu(&rig3.dbzz)); const duez = try fron.fronDuez(&rig3.dbzz, rig3.aren.allocator(), 10, 10); try std.testing.expectEqual(@as(usize, 1), duez.len); try std.testing.expectEqualStrings("http://a/1", duez[0].urlz); try std.testing.expect(!try fron.fronAddz(&rig3.dbzz, "http://a/2", "a", 20)); }
test "unknown URL is NotFound, huge try counts do not overflow" { var rig3: Rigg = undefined; try rig3.upzz(); defer rig3.down(); try std.testing.expectError(error.NotFound, fron.fronDone(&rig3.dbzz, "http://nope/")); try std.testing.expectError(error.NotFound, fron.fronFail(&rig3.dbzz, "http://nope/", "x", 0, 3, 1)); _ = try fron.fronAddz(&rig3.dbzz, "http://a/9", "a", 0); var indx: usize = 0; while (indx < 40) : (indx += 1) _ = try fron.fronFail(&rig3.dbzz, "http://a/9", "x", 0, 1000, std.math.maxInt(i64) / 4); }
